WITH `t0` AS (SELECT `tenantId`, `entityId`, `version`, `effectiveAt`, `market_stock_total`, `market_stock_p50`, `market_lead_time_p50_days` FROM `metric_group_ots_component_market_availability` FINAL WHERE `tenantId` = {p0:String}), `t1` AS (SELECT `tenantId`, `entityId`, `version`, `effectiveAt`, `stock_index` FROM `metric_group_ots_component_indices` FINAL WHERE `tenantId` = {p1:String}) SELECT `__typedhouse_input`.`__typedhouse_leaf_1` AS `entityId`, `__typedhouse_input`.`__typedhouse_leaf_2` AS `category`, `__typedhouse_input`.`__typedhouse_leaf_13` AS `stockTotal`, `__typedhouse_input`.`__typedhouse_leaf_15` AS `stockP50`, `__typedhouse_input`.`__typedhouse_leaf_17` AS `leadDays`, `__typedhouse_input`.`__typedhouse_leaf_26` AS `stockIndex`, greatest(`__typedhouse_input`.`__typedhouse_leaf_11`, `__typedhouse_input`.`__typedhouse_leaf_22`) AS `asOf` FROM (SELECT `c`.`entityId` AS `__typedhouse_leaf_1`, `c`.`category` AS `__typedhouse_leaf_2`, `a`.`effectiveAt` AS `__typedhouse_leaf_11`, `a`.`market_stock_total` AS `__typedhouse_leaf_13`, `a`.`market_stock_p50` AS `__typedhouse_leaf_15`, `a`.`market_lead_time_p50_days` AS `__typedhouse_leaf_17`, `i`.`effectiveAt` AS `__typedhouse_leaf_22`, `i`.`stock_index` AS `__typedhouse_leaf_26` FROM (SELECT `__typedhouse_input`.`entityId`, `__typedhouse_input`.`category` FROM (SELECT `entityId`, `category` FROM `entity_ots_component` WHERE `tenantId` = {p2:String} AND `state` = {p3:String}) AS `__typedhouse_input` WHERE startsWith(`__typedhouse_input`.`category`, {p4:String})) AS `c` INNER ALL JOIN (SELECT `m`.`entityId` AS `entityId`, `m`.`effectiveAt` AS `effectiveAt`, `m`.`market_stock_total` AS `market_stock_total`, `m`.`market_stock_p50` AS `market_stock_p50`, `m`.`market_lead_time_p50_days` AS `market_lead_time_p50_days` FROM `t0` AS `m` INNER ALL JOIN (SELECT `tenantId`, `entityId`, max(`version`) AS `version` FROM `t0` GROUP BY `tenantId`, `entityId`) AS `v` ON `m`.`tenantId` = `v`.`tenantId` AND `m`.`entityId` = `v`.`entityId` AND `m`.`version` = `v`.`version`) AS `a` ON `c`.`entityId` = `a`.`entityId` INNER ALL JOIN (SELECT `m`.`entityId` AS `entityId`, `m`.`effectiveAt` AS `effectiveAt`, `m`.`stock_index` AS `stock_index` FROM `t1` AS `m` INNER ALL JOIN (SELECT `tenantId`, `entityId`, max(`version`) AS `version` FROM `t1` GROUP BY `tenantId`, `entityId`) AS `v` ON `m`.`tenantId` = `v`.`tenantId` AND `m`.`entityId` = `v`.`entityId` AND `m`.`version` = `v`.`version`) AS `i` ON `c`.`entityId` = `i`.`entityId`) AS `__typedhouse_input`
